{
  "type": "paragraph",
  "inlineContent": [
    {
      "inlineContent": [
        {
          "type": "text",
          "text": "Add padding around interactive elements to create comfortable hit regions."
        }
      ],
      "type": "strong"
    },
    {
      "text": " You might need to experiment to determine the right size for an element\u2019s hit region. If the hit region is too small, it can make people feel that they have to be extra precise when interacting with the element. On the other hand, when an element\u2019s hit region is too large, people can feel that it takes a lot of effort to pull the pointer away from the element. In general, it works well to add about 12 points of padding around elements that include a bezel; for elements without a bezel, it works well to add about 24 points of padding around the element\u2019s visible edges.",
      "type": "text"
    }
  ]
}
